<?php
declare(strict_types=1);
namespace App\Application\Catalog\Service;
use App\Application\Catalog\DTO\Request\CreatePositionRequestDto; use App\Application\Catalog\DTO\Response\PositionResponseDto; use App\Application\Catalog\Mapper\PositionResponseMapper; use App\Application\Catalog\Port\TransactionManagerInterface; use App\Domain\Catalog\Entity\Position; use App\Domain\Catalog\Repository\ExamRepositoryInterface; use App\Domain\Catalog\Repository\PositionRepositoryInterface;
final class CreatePositionService { public function __construct(private readonly ExamRepositoryInterface $exams,private readonly PositionRepositoryInterface $positions,private readonly PositionResponseMapper $mapper,private readonly TransactionManagerInterface $transactions){} public function create(CreatePositionRequestDto $r): PositionResponseDto { $name=trim($r->name); $emphasis=$r->emphasis===null?null:trim($r->emphasis); if($name===''||mb_strlen($name)>190||($emphasis!==null&&($emphasis===''||mb_strlen($emphasis)>190))) throw new \InvalidArgumentException('Dados do cargo invalidos.'); if($this->exams->findById($r->examId)===null) throw new \DomainException('Concurso nao encontrado.'); $p=new Position($this->uuid(),$r->examId,$name,$emphasis); $this->transactions->transactional(fn()=>$this->positions->save($p)); return $this->mapper->map($p); } private function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));} }
